(window.TIMELINE_TRANSLATIONS=window.TIMELINE_TRANSLATIONS||{})["zh-yue"]={"qin-dynasty":{"id":"qin-dynasty","title":"秦朝","summary":"秦國喺嬴政帶領之下征服咗主要對手，嬴政之後採用「秦始皇」呢個皇帝稱號。秦朝只係維持咗好短時間，但係佢嘅軍事同行政做法影響咗後來嘅漢朝。","began":"秦國嘅征戰最終達成統一，嬴政自立為皇帝。","ended":"秦始皇死後幾年，秦朝就崩潰；各方勢力互相爭鬥，之後漢朝先至建立帝制統治。","why":"建立咗一套帝制政治框架，俾後世朝代沿用同調整。"},"confucius":{"id":"confucius","title":"孔子教導德治","summary":"孔子喺春秋時期講學。佢重視道德操守、家庭責任、學習，同埋君主要以德治國嘅責任。佢嘅學說成為一個重要嘅思想傳統，後來嘅皇朝政府將儒家經典放喺官方教育嘅核心。","why":"佢嘅學說影響咗成個東亞嘅政治倫理、教育同家庭理想。"},"stonewall-riots":{"id":"stonewall-riots","title":"石牆起義","summary":"顧客同支持者喺紐約石牆酒吧反抗警察突擊搜查，之後仲有更多衝突同示威。呢場起義成為一個重要參照點，推動緊一場反對迫害性小眾、日益壯大嘅運動。","why":"石牆幫手推動咗同志解放同後來嘅 LGBTQ 組織工作，不過佢唔係第一次反抗行動。"}};
